import {
  atlasDataSchema,
  decodeAtlasAllocation,
  encodeAtlasAllocation,
  type AtlasAllocation,
  type AtlasData,
  type AtlasNode
} from "@poe-odyssey/core";
import {
  Check,
  Clipboard,
  Download,
  ExternalLink,
  Focus,
  Minus,
  Plus,
  RotateCcw,
  Search,
  Share2,
  Upload
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { PageTitle } from "../App";
import { loadAtlasAllocation, saveAtlasAllocation } from "../storage";

function allocation(ids: string[]): AtlasAllocation {
  return {
    version: "3.29",
    allocatedNodeIds: ids,
    points: ids.length,
    updatedAt: new Date().toISOString()
  };
}

function nodeMatches(node: AtlasNode, query: string): boolean {
  const haystack = [
    node.name.zhTW,
    node.name.en,
    ...node.stats.zhTW,
    ...node.stats.en
  ].join(" ").toLocaleLowerCase();
  return haystack.includes(query.toLocaleLowerCase());
}

export function AtlasPage() {
  const [data, setData] = useState<AtlasData>();
  const [allocated, setAllocated] = useState<string[]>([]);
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState<string>();
  const [message, setMessage] = useState("");
  const [shareCode, setShareCode] = useState("");
  const [zoom, setZoom] = useState(1);
  const [center, setCenter] = useState({ x: 0, y: 0 });
  const [searchParams, setSearchParams] = useSearchParams();

  useEffect(() => {
    const controller = new AbortController();
    void Promise.all([
      fetch(`${import.meta.env.BASE_URL}data/atlas/3.29.json`, { signal: controller.signal })
        .then(async (response) => {
          if (!response.ok) throw new Error(`Atlas data returned ${response.status}`);
          return atlasDataSchema.parse(await response.json());
        }),
      loadAtlasAllocation("3.29")
    ]).then(([atlas, stored]) => {
      setData(atlas);
      setCenter({
        x: (atlas.bounds.minX + atlas.bounds.maxX) / 2,
        y: (atlas.bounds.minY + atlas.bounds.maxY) / 2
      });
      const shared = searchParams.get("share");
      if (shared) {
        const parsed = decodeAtlasAllocation(shared);
        setAllocated(parsed.allocatedNodeIds.filter((id) => atlas.nodes.some((node) => node.id === id)));
      } else if (stored) {
        setAllocated(stored.allocatedNodeIds.filter((id) => atlas.nodes.some((node) => node.id === id)));
      }
    }).catch((reason: unknown) => {
      if ((reason as { name?: string }).name !== "AbortError") {
        setMessage(reason instanceof Error ? reason.message : "輿圖資料載入失敗");
      }
    });
    return () => controller.abort();
  }, []);

  useEffect(() => {
    if (data) void saveAtlasAllocation(allocation(allocated));
  }, [allocated, data]);

  const nodeMap = useMemo(() => new Map(data?.nodes.map((node) => [node.id, node]) ?? []), [data]);
  const selected = selectedId ? nodeMap.get(selectedId) : undefined;
  const matches = useMemo(() =>
    query.trim() ? (data?.nodes.filter((node) => nodeMatches(node, query.trim())).slice(0, 40) ?? []) : [],
  [data, query]);

  const edges = useMemo(() => {
    if (!data) return [];
    const seen = new Set<string>();
    return data.nodes.flatMap((node) => node.connections.flatMap((targetId) => {
      const target = nodeMap.get(targetId);
      if (!target) return [];
      const key = [node.id, targetId].sort().join(":");
      if (seen.has(key)) return [];
      seen.add(key);
      return [{ key, source: node, target }];
    }));
  }, [data, nodeMap]);

  const viewBox = useMemo(() => {
    if (!data) return "0 0 100 100";
    const width = (data.bounds.maxX - data.bounds.minX) / zoom;
    const height = (data.bounds.maxY - data.bounds.minY) / zoom;
    return `${center.x - width / 2} ${center.y - height / 2} ${width} ${height}`;
  }, [center, data, zoom]);

  function toggleNode(node: AtlasNode) {
    setMessage("");
    if (allocated.includes(node.id)) {
      const allocatedNeighbours = node.connections.filter((id) => allocated.includes(id));
      if (allocatedNeighbours.length > 1) {
        setMessage("這個節點仍連接多個已配置節點；請先從路徑末端退點。");
        return;
      }
      setAllocated(allocated.filter((id) => id !== node.id));
      return;
    }
    if (allocated.length && !node.connections.some((id) => allocated.includes(id))) {
      setMessage("配置必須接到現有路徑。第一點可從任意起點開始，之後請沿連線配置。");
      return;
    }
    setAllocated([...allocated, node.id]);
  }

  function focusNode(node: AtlasNode) {
    setSelectedId(node.id);
    setCenter({ x: node.x, y: node.y });
    setZoom(Math.max(zoom, 2.5));
  }

  async function share() {
    const code = encodeAtlasAllocation(allocation(allocated));
    setSearchParams({ share: code });
    const url = new URL(window.location.href);
    url.hash = `#/atlas?share=${encodeURIComponent(code)}`;
    await navigator.clipboard.writeText(url.toString());
    setMessage("分享連結已複製。");
  }

  function importCode() {
    try {
      const parsed = decodeAtlasAllocation(shareCode);
      const validIds = parsed.allocatedNodeIds.filter((id) => nodeMap.has(id));
      setAllocated(validIds);
      setMessage(`已匯入 ${validIds.length} 點。`);
    } catch (reason) {
      setMessage(reason instanceof Error ? reason.message : "分享碼無法解析");
    }
  }

  return (
    <div className="page atlas-page">
      <PageTitle
        eyebrow="ATLAS PASSIVE PLANNER · OFFICIAL EXPORT"
        title="繁中輿圖天賦模擬器"
        description="使用 GGG 官方 3.29 Atlas Tree 匯出資料；搜尋、配置點數、保存並分享自己的刷圖路線。"
      >
        <a className="button secondary" href="https://www.pathofexile.com/fullscreen-atlas-skill-tree" target="_blank" rel="noreferrer">
          官方天賦樹 <ExternalLink size={15} />
        </a>
      </PageTitle>

      <section className="atlas-toolbar panel">
        <label className="search-field">
          <Search size={17} />
          <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜尋機制、節點或效果…" />
        </label>
        <div className="atlas-points"><strong>{allocated.length}</strong><span>已配置點數</span></div>
        <button className="button secondary" onClick={() => { setAllocated([]); setMessage("配置已清除。"); }}><RotateCcw size={15} /> 清除</button>
        <button className="button primary" onClick={() => void share()}><Share2 size={15} /> 分享</button>
      </section>

      {matches.length > 0 && (
        <div className="atlas-search-results">
          {matches.map((node) => (
            <button key={node.id} onClick={() => focusNode(node)}>
              <Focus size={14} /><span>{node.name.zhTW}<small>{node.name.en}</small></span>
            </button>
          ))}
        </div>
      )}

      {message && <div className="inline-message">{message}</div>}

      <section className="atlas-workspace">
        <div className="atlas-canvas panel">
          {!data ? <div className="atlas-loading">載入官方天賦資料…</div> : (
            <svg viewBox={viewBox} role="img" aria-label="輿圖天賦樹">
              <g className="atlas-edges">
                {edges.map(({ key, source, target }) => {
                  const active = allocated.includes(source.id) && allocated.includes(target.id);
                  return <line key={key} x1={source.x} y1={source.y} x2={target.x} y2={target.y} className={active ? "active" : ""} />;
                })}
              </g>
              <g className="atlas-nodes">
                {data.nodes.map((node) => {
                  const active = allocated.includes(node.id);
                  const highlighted = selectedId === node.id || (query.trim() && nodeMatches(node, query.trim()));
                  return (
                    <g
                      key={node.id}
                      className={`${node.kind} ${active ? "active" : ""} ${highlighted ? "highlighted" : ""}`}
                      transform={`translate(${node.x} ${node.y})`}
                      onClick={() => { setSelectedId(node.id); toggleNode(node); }}
                      role="button"
                      aria-label={`${node.name.zhTW}${active ? " 已配置" : ""}`}
                    >
                      <circle r={node.kind === "keystone" ? 78 : node.kind === "notable" ? 60 : 34} />
                    </g>
                  );
                })}
              </g>
            </svg>
          )}
          <div className="atlas-zoom">
            <button onClick={() => setZoom(Math.max(1, zoom - 0.5))} aria-label="縮小"><Minus size={15} /></button>
            <span>{zoom.toFixed(1)}×</span>
            <button onClick={() => setZoom(Math.min(5, zoom + 0.5))} aria-label="放大"><Plus size={15} /></button>
          </div>
        </div>

        <aside className="atlas-inspector panel">
          {selected ? (
            <>
              <span className={`node-kind ${selected.kind}`}>{selected.kind}</span>
              <h2>{selected.name.zhTW}</h2>
              <small>{selected.name.en}</small>
              <ul>{selected.stats.zhTW.map((stat, index) => <li key={`${stat}-${index}`}>{stat}<small>{selected.stats.en[index]}</small></li>)}</ul>
              <button className={`button ${allocated.includes(selected.id) ? "secondary" : "primary"}`} onClick={() => toggleNode(selected)}>
                {allocated.includes(selected.id) ? <><Minus size={15} /> 退還此點</> : <><Check size={15} /> 配置此點</>}
              </button>
            </>
          ) : (
            <div className="empty-inspector"><Focus size={28} /><p>點選節點查看雙語效果。配置會自動保存在此瀏覽器。</p></div>
          )}
          <div className="atlas-import">
            <label>分享碼</label>
            <textarea value={shareCode} onChange={(event) => setShareCode(event.target.value)} placeholder="3.29:123,456,789" />
            <div>
              <button className="button secondary" onClick={() => setShareCode(encodeAtlasAllocation(allocation(allocated)))}><Download size={14} /> 匯出</button>
              <button className="button secondary" onClick={importCode}><Upload size={14} /> 匯入</button>
              <button className="button secondary" onClick={() => void navigator.clipboard.writeText(shareCode)}><Clipboard size={14} /></button>
            </div>
          </div>
        </aside>
      </section>
      <p className="source-footnote">資料：Grinding Gear Games atlastree-export · {data?.nodes.length ?? 0} 個可配置節點 · 中文採遊戲機制詞彙與英文原文並列。</p>
    </div>
  );
}
